type Manifest={ok:boolean;appVersion:string;revisions:Record<string,string>}
let authManifest:Manifest|null=null
let curriculumAccessToken=''
function studentHeaders():Record<string,string>{return curriculumAccessToken?{Authorization:`Bearer ${curriculumAccessToken}`}:{}}
function getManifest(){return Promise.resolve(authManifest)}
function mergeDelta<T extends {id:number}>(base:T[],changed:T[],deleted:number[]){const gone=new Set(deleted||[]),m=new Map(base.filter(x=>!gone.has(x.id)).map(x=>[x.id,x]));for(const x of changed||[])if(!gone.has(x.id))m.set(x.id,x);return [...m.values()].sort((a,b)=>b.id-a.id)}
async function loadPublicContent(section:Section){
 const mem=publicContentCache.get(section);if(mem)return mem
 const key=`content:${section}`,saved=await cacheGet<Content[]>(key),manifest=await getManifest()
 if(saved){
   let data=saved.data
   if(manifest&&saved.appVersion===manifest.appVersion&&saved.revision!==manifest.revisions[section]){const d=await fetch(`/api/sync?resource=${encodeURIComponent(section)}&since=${encodeURIComponent(saved.revision||'0')}`,{headers:studentHeaders()}).then(r=>r.json()).catch(()=>null);if(d?.ok){data=mergeDelta(data,d.changed||[],d.deleted||[]).filter(x=>x.status==='published');await cacheSet(key,{data,revision:d.revision||manifest.revisions[section],appVersion:manifest.appVersion,savedAt:Date.now()})}}
   else if(manifest&&saved.appVersion!==manifest.appVersion){const d=await fetch(`/api/content?section=${encodeURIComponent(section)}`,{headers:studentHeaders()}).then(r=>r.json()).catch(()=>null);if(d?.ok){data=d.items||[];await cacheSet(key,{data,revision:manifest.revisions[section]||'0',appVersion:manifest.appVersion,savedAt:Date.now()})}}
   publicContentCache.set(section,data);return data
 }
 const d=await fetch(`/api/content?section=${encodeURIComponent(section)}`,{headers:studentHeaders()}).then(r=>r.json()).catch(()=>null);const fallback=(!d?.ok)?await fetch('/curriculum-content.json').then(r=>r.ok?r.json():[]).catch(()=>[]):[];const data=d?.ok?(d.items as Content[]):(Array.isArray(fallback)?fallback.filter((x:Content)=>x.section===section&&x.status==='published'):[])
 if(d?.ok){const m=manifest||await getManifest();await cacheSet(key,{data,revision:m?.revisions?.[section]||'0',appVersion:m?.appVersion||MEWAY_BUILD_ID,savedAt:Date.now()})}publicContentCache.set(section,data);return data
}
function clearPublicContentCache(section?:Section){if(section){publicContentCache.delete(section);void cacheDelete(`content:${section}`)}else{publicContentCache.clear();for(const s of ['games','quizzes','words','challenges','rewards'] as Section[])void cacheDelete(`content:${s}`)}}
function invalidateAdminCaches(){adminBootstrapCache=null;adminBootstrapPromise=null;adminStudentsCache=null;adminSectionCache.clear();adminSectionPromises.clear();}
async function loadMissionCache(all=false){
 const key='missions',saved=await cacheGet<{missions:Mission[];settings:MewaySettings;settingsRevision?:string}>(key),manifest=await getManifest()
 if(saved){let data=saved.data;if(manifest&&saved.appVersion===manifest.appVersion&&saved.revision!==manifest.revisions.missions){const d=await fetch(`/api/sync?resource=missions&since=${encodeURIComponent(saved.revision||'0')}`,{headers:studentHeaders()}).then(r=>r.json()).catch(()=>null);if(d?.ok)data={...data,missions:mergeDelta(data.missions,d.changed||[],d.deleted||[]).filter((x:any)=>x.status==='published')}}if(manifest&&saved.appVersion===manifest.appVersion&&(data.settingsRevision||'0')!==manifest.revisions.settings){const d=await fetch('/api/settings',{headers:studentHeaders()}).then(r=>r.json()).catch(()=>null);if(d?.ok)data={...data,settings:d.settings||defaultSettings,settingsRevision:manifest.revisions.settings}}if(manifest&&saved.appVersion!==manifest.appVersion){const d=await fetch('/api/missions',{headers:studentHeaders()}).then(r=>r.json()).catch(()=>null);if(d?.ok)data={missions:d.missions||[],settings:d.settings||defaultSettings,settingsRevision:manifest.revisions.settings}}if(manifest)await cacheSet(key,{data,revision:manifest.revisions.missions||saved.revision,appVersion:manifest.appVersion,savedAt:Date.now()});return {...data,missions:all?data.missions:data.missions.slice(0,40)}}
 const d=await fetch('/api/missions',{headers:studentHeaders()}).then(r=>r.json()).catch(()=>null);const fallback=(!d?.ok)?await fetch('/curriculum-missions.json').then(r=>r.ok?r.json():[]).catch(()=>[]):[];const m=manifest||await getManifest();const data={missions:d?.ok?d.missions||[]:(Array.isArray(fallback)?fallback.filter((x:Mission)=>x.status==='published'):[]),settings:d?.settings||defaultSettings,settingsRevision:m?.revisions?.settings||'0'};if(d?.ok){await cacheSet(key,{data,revision:m?.revisions?.missions||'0',appVersion:m?.appVersion||MEWAY_BUILD_ID,savedAt:Date.now()})}return {...data,missions:all?data.missions:data.missions.slice(0,40)}
}

