 const [localPrefs,setLocalPrefs]=useState<LocalPrefs>(loadLocalPrefs),[uiConfig,setUiConfig]=useState<UIConfig>(()=>({...DEFAULT_UI_CONFIG,...((discordAuth as any).uiConfig||{})}))
