       if(result.progress){setXp(Number(result.progress.xp)||0);setCompleted(result.progress.completedMissions||[]);setCompletedContent(result.progress.completedContent||[]);try{const old=JSON.parse(localStorage.getItem('meway-progress')||'{}');localStorage.setItem('meway-progress',JSON.stringify({...old,...result.progress}));const uid=discordAuth.user?.id;if(uid){void cacheGet<MewayAuthResult>(`auth-bootstrap:${uid}`).then(saved=>{if(saved?.data){const next={...saved.data,progress:result.progress};return cacheSet(`auth-bootstrap:${uid}`,{...saved,data:next,savedAt:Date.now()})}})}}catch{}}
