 const recordAnswer=(ok:boolean,topic='Общее')=>{const ac=answerCount+1,ca=correctAnswers+(ok?1:0),mi=mistakes+(ok?0:1);const prev=sectionStats[topic]||{total:0,correct:0};const ss={...sectionStats,[topic]:{total:prev.total+1,correct:prev.correct+(ok?1:0)}};const today=new Date().toISOString().slice(0,10),da=dailyAnswerDate===today?dailyAnswers+1:1;setAnswerCount(ac);setCorrectAnswers(ca);setMistakes(mi);setSectionStats(ss);setDailyAnswers(da);setDailyAnswerDate(today);persist({answerCount:ac,correctAnswers:ca,mistakes:mi,sectionStats:ss,dailyAnswers:da,dailyAnswerDate:today})};const recordMistake=()=>recordAnswer(false)
